{
  "packet_id": "H6-T01-1",
  "claim_id": "C061",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C061.component",
    "value": "A trial should be stopped or revised if it causes unacceptable disruption.",
    "scope": "A conditional service bound; the mapping does not choose between stopping and revision.",
    "provenance": {
      "refs": [
        {
          "source_id": "P028",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited span explicitly supplies the disruption condition and both permitted responses."
    }
  },
  "signal_basis": {
    "component_id": "C061.signal_basis",
    "value": "Continue measurements during the predefined trial period, using service-impact thresholds set before implementation; the relevant trigger is unacceptable disruption caused by the trial.",
    "scope": "A conditional trial-management trigger. Temporal coincidence alone does not establish that the trial caused disruption.",
    "provenance": {
      "refs": [
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P028",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply continued trial measurement, advance service-impact thresholds, the disruption trigger, and the limitation on causal identification."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C061.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as an explicit conditional service bound; no unresolved empirical relation is needed to warrant that bound."
    }
  },
  "rationale": "Given the stipulated trigger, disruption caused by the trial that exceeds the accepted service bound licenses stopping or revising it. The claim supplies a decision constraint without asserting that temporal observations establish causation or selecting between the two responses.",
  "uncertainty": "The packet does not establish that any trial has caused unacceptable disruption. That does not undermine this conditional claim.",
  "anomalies": []
}
